## 10. Code Examples & References
### Minimal Email Integration (SendGrid)
```typescript
import sgMail from "@sendgrid/mail";

sgMail.setApiKey(process.env.SENDGRID_API_KEY!);

interface EmailParams {
  to: string;
  subject: string;
  html: string;
  text?: string;
}

export async function sendEmail(params: EmailParams): Promise<DeliveryResult> {
  try {
    const msg = {
      to: params.to,
      from: "noreply@freshschedules.com",
      subject: params.subject,
      html: params.html,
      text: params.text || stripHtml(params.html),
    };

    const [response] = await sgMail.send(msg);

    return {
      success: true,
      provider: "sendgrid",
      messageId: response.headers["x-message-id"],
    };
  } catch (error) {
    console.error("Email send failed", { params, error });
    return {
      success: false,
      provider: "sendgrid",
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}
```

### Minimal SMS Integration (Twilio)
```typescript
import twilio from "twilio";

const client = twilio(process.env.TWILIO_ACCOUNT_SID, process.env.TWILIO_AUTH_TOKEN);

interface SMSParams {
  to: string; // E.164 format: +15551234567
  body: string;
}

export async function sendSMS(params: SMSParams): Promise<DeliveryResult> {
  try {
    const message = await client.messages.create({
      to: params.to,
      from: process.env.TWILIO_PHONE_NUMBER,
      body: params.body,
    });

    return {
      success: true,
      provider: "twilio",
      messageId: message.sid,
    };
  } catch (error) {
    console.error("SMS send failed", { params, error });
    return {
      success: false,
      provider: "twilio",
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}
```

### Minimal Push Notification Integration (FCM)
```typescript
import { getMessaging } from "firebase-admin/messaging";

interface PushParams {
  token: string; // FCM device token
  title: string;
  body: string;
  data?: Record<string, string>;
}

export async function sendPush(params: PushParams): Promise<DeliveryResult> {
  try {
    const message = {
      token: params.token,
      notification: {
        title: params.title,
        body: params.body,
      },
      data: params.data,
      android: {
        priority: "high" as const,
      },
      apns: {
        payload: {
          aps: {
            sound: "default",
          },
        },
      },
    };

    const messageId = await getMessaging().send(message);

    return {
      success: true,
      provider: "fcm",
      messageId,
    };
  } catch (error) {
    console.error("Push send failed", { params, error });
    return {
      success: false,
      provider: "fcm",
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}
```

